INSERT OR IGNORE INTO guide_sections (id, guide_id, title, section_type, content_markdown, position, meta_json)
SELECT 'guide-iroi-0031-builds', 'guide-iroi-0031', 'Дуги, консоль и характеристики', 'builds', 'The Wrong Gate — основной выбор; Clear Skies — доступная альтернатива. Speedy Hedgehog помогает со сверхспособностью и командным усилением. Атака важна для её эффектов; энергию и лечение подбирайте под фактическую выживаемость отряда.', 2, '{"checkedAt":"2026-10-21","sourceUrls":["https://nte.perfectworld.com/ru/main.html?nav=2","https://nte.perfectworld.com/en/article/news/gamenews/20260728/263296.html","https://www.kaiden.gg/nte/characters/iroi/","https://neverness.gg/iroi-nte-build/"],"liveTested":false}' WHERE EXISTS (SELECT 1 FROM expansion_guides_0031 WHERE id = 'guide-iroi-0031');

INSERT OR IGNORE INTO guide_sections (id, guide_id, title, section_type, content_markdown, position, meta_json)
SELECT 'guide-iroi-0031-skill-priority', 'guide-iroi-0031', 'Приоритет навыков', 'skill-priority', 'В первую очередь проверяйте развитие сверхспособности и навыка перенаправления, затем навыка поддержки. При смене задачи с лечения на личный урон приоритеты могут измениться.', 3, '{"checkedAt":"2026-10-21","sourceUrls":["https://nte.perfectworld.com/ru/main.html?nav=2","https://nte.perfectworld.com/en/article/news/gamenews/20260728/263296.html","https://www.kaiden.gg/nte/characters/iroi/","https://neverness.gg/iroi-nte-build/"],"liveTested":false}' WHERE EXISTS (SELECT 1 FROM expansion_guides_0031 WHERE id = 'guide-iroi-0031');

INSERT OR IGNORE INTO guide_sections (id, guide_id, title, section_type, content_markdown, position, meta_json)
