SELECT 'guide-iroi-0031-rotations', 'guide-iroi-0031', 'Базовая ротация', 'rotations', '1. Используйте навык Ирой до выхода основного ДД, чтобы подготовить Regression и связанные усиления.
2. Переключитесь на персонажей реакций и обновите командные усиления.
3. Проведите окно урона основного ДД, пока Ирой поддерживает его из резерва.
4. Возвращайтесь к Ирой для обновления навыка; выбирайте применение сверхспособности по состоянию команды и ресурсу Imagination.
5. Сохраняйте возможность восстановления союзника через сверхспособность, когда сработала Regression.', 5, '{"checkedAt":"2026-10-21","sourceUrls":["https://nte.perfectworld.com/ru/main.html?nav=2","https://nte.perfectworld.com/en/article/news/gamenews/20260728/263296.html","https://www.kaiden.gg/nte/characters/iroi/","https://neverness.gg/iroi-nte-build/"],"liveTested":false}' WHERE EXISTS (SELECT 1 FROM expansion_guides_0031 WHERE id = 'guide-iroi-0031');

