UPDATE tierlists SET patch_version = '1.4', changelog_json = '["21.10.2026: каталог расширен до 24 персонажей. Аканэ Рин пока без оценки.","Ориентир: Icy Veins, 28.09.2026, https://www.icy-veins.com/neverness-to-everness/tier-list . S-ранговые персонажи оценены при A0, A-ранговые при A6; роли и условия различаются.","Изменённые редактором позиции сохранены. Внешняя шкала Kaiden T0/T1 не переводится автоматически в S/A.","Первый публичный редакционный список"]', updated_at = CURRENT_TIMESTAMP WHERE id = 'tier-base-10' AND patch_version = '1.1' AND changelog_json = '["Первый публичный редакционный список"]';
